CREATE TABLE public.properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),branch_id uuid,created_by uuid NOT NULL DEFAULT auth.uid(),title text NOT NULL CHECK(length(title) BETWEEN 3 AND 160),description text NOT NULL DEFAULT '' CHECK(length(description)<=6000),location text NOT NULL CHECK(length(location) BETWEEN 2 AND 200),category text NOT NULL DEFAULT 'HOUSE' CHECK(category IN ('HOUSE','PLOT','APARTMENT','COMMERCIAL')),intent text NOT NULL DEFAULT 'sale' CHECK(intent IN ('sale','rent')),price numeric NOT NULL DEFAULT 0 CHECK(price>=0),area numeric NOT NULL DEFAULT 0 CHECK(area>=0),area_unit text NOT NULL DEFAULT 'Marla' CHECK(area_unit IN ('Marla','Kanal','sq ft')),bedrooms integer NOT NULL DEFAULT 0 CHECK(bedrooms BETWEEN 0 AND 100),bathrooms integer NOT NULL DEFAULT 0 CHECK(bathrooms BETWEEN 0 AND 100),amenities text[] NOT NULL DEFAULT '{}',cover_path text,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','published','archived')),availability text NOT NULL DEFAULT 'available' CHECK(availability IN ('available','sold','rented','unavailable')),verified_at timestamptz,reference_code text NOT NULL DEFAULT ('KP-'||upper(substr(gen_random_uuid()::text,1,8))) UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(branch_id,tenant_id) REFERENCES public.branches(id,tenant_id),UNIQUE(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.properties TO authenticated; GRANT ALL ON public.properties TO service_role; ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY; CREATE INDEX properties_tenant_status ON public.properties(tenant_id,status);
CREATE POLICY property_read ON public.properties FOR SELECT TO authenticated USING(public.record_access(tenant_id,branch_id,created_by) OR public.is_platform_admin()); CREATE POLICY property_insert ON public.properties FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND status='draft' AND verified_at IS NULL AND public.record_access(tenant_id,branch_id,created_by)); CREATE POLICY property_update ON public.properties FOR UPDATE TO authenticated USING(public.record_access(tenant_id,branch_id,created_by) OR public.is_platform_admin()) WITH CHECK(public.record_access(tenant_id,branch_id,created_by) OR public.is_platform_admin()); CREATE POLICY property_delete ON public.properties FOR DELETE TO authenticated USING(status IN ('draft','archived') AND public.record_access(tenant_id,branch_id,created_by));
CREATE FUNCTION public.guard_property() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF new.tenant_id<>old.tenant_id OR new.created_by<>old.created_by OR new.branch_id IS DISTINCT FROM old.branch_id THEN RAISE EXCEPTION 'Ownership cannot be changed'; END IF; IF NOT public.is_platform_admin() THEN IF new.verified_at IS DISTINCT FROM old.verified_at OR (new.status='published' AND old.status<>'published') THEN RAISE EXCEPTION 'Moderator approval required'; END IF; IF old.status='published' AND new.status<>'archived' THEN new.status='review'; new.verified_at=NULL; END IF; END IF; END IF; IF new.cover_path IS NOT NULL AND new.cover_path NOT LIKE new.created_by::text||'/'||new.id::text||'/%' THEN RAISE EXCEPTION 'Invalid media path'; END IF; new.updated_at=now(); RETURN new; END $$; CREATE TRIGGER property_guard BEFORE INSERT OR UPDATE ON public.properties FOR EACH ROW EXECUTE FUNCTION public.guard_property();
CREATE TABLE public.leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),branch_id uuid,property_id uuid,assigned_to uuid,created_by uuid DEFAULT auth.uid(),name text NOT NULL CHECK(length(name) BETWEEN 2 AND 100),phone text NOT NULL CHECK(phone ~ '^[+0-9 ()-]{7,30}$'),email text CHECK(email IS NULL OR (length(email)<=255 AND email ~ '^[^ @]+@[^ @]+\.[^ @]+$')),message text NOT NULL DEFAULT '' CHECK(length(message)<=2000),stage text NOT NULL DEFAULT 'new' CHECK(stage IN ('new','contacted','qualified','visit scheduled','proposal/negotiation','won','lost')),source text NOT NULL DEFAULT 'manual' CHECK(length(source)<=100),attribution jsonb NOT NULL DEFAULT '{}',contact_preference text NOT NULL DEFAULT 'phone' CHECK(contact_preference IN ('phone','whatsapp','email')),consent boolean NOT NULL DEFAULT false,follow_up_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(property_id,tenant_id) REFERENCES public.properties(id,tenant_id),FOREIGN KEY(branch_id,tenant_id) REFERENCES public.branches(id,tenant_id));
GRANT SELECT,INSERT,UPDATE ON public.leads TO authenticated; GRANT ALL ON public.leads TO service_role; ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY; CREATE INDEX leads_tenant_stage ON public.leads(tenant_id,stage); CREATE INDEX leads_assigned ON public.leads(assigned_to);
CREATE POLICY lead_read ON public.leads FOR SELECT TO authenticated USING(public.record_access(tenant_id,branch_id,assigned_to,true)); CREATE POLICY lead_insert ON public.leads FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND assigned_to=auth.uid() AND public.record_access(tenant_id,branch_id,assigned_to,true)); CREATE POLICY lead_update ON public.leads FOR UPDATE TO authenticated USING(public.record_access(tenant_id,branch_id,assigned_to,true)) WITH CHECK(public.record_access(tenant_id,branch_id,assigned_to,true));
CREATE FUNCTION public.guard_lead() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.tenant_id<>old.tenant_id OR new.property_id IS DISTINCT FROM old.property_id OR new.branch_id IS DISTINCT FROM old.branch_id OR new.created_by IS DISTINCT FROM old.created_by THEN RAISE EXCEPTION 'Lead ownership cannot be changed'; END IF; IF new.assigned_to IS DISTINCT FROM old.assigned_to THEN IF NOT public.can_manage(old.tenant_id) OR NOT EXISTS(SELECT 1 FROM public.memberships WHERE tenant_id=old.tenant_id AND user_id=new.assigned_to AND role IN ('owner','admin','sales_manager','agent')) THEN RAISE EXCEPTION 'Assignment not allowed'; END IF; END IF; new.updated_at=now(); RETURN new; END $$; CREATE TRIGGER lead_guard BEFORE UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.guard_lead();
CREATE TABLE public.lead_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid NOT NULL REFERENCES public.leads(id) ON DELETE CASCADE,author_id uuid NOT NULL DEFAULT auth.uid(),note text NOT NULL CHECK(length(note) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.lead_activities TO authenticated; GRANT ALL ON public.lead_activities TO service_role; ALTER TABLE public.lead_activities ENABLE ROW LEVEL SECURITY; CREATE POLICY activity_read ON public.lead_activities FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.leads WHERE id=lead_id)); CREATE POLICY activity_insert ON public.lead_activities FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND EXISTS(SELECT 1 FROM public.leads WHERE id=lead_id));
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,tenant_id uuid,action text NOT NULL,record_id uuid,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.can_manage(tenant_id) OR public.is_platform_admin());
CREATE FUNCTION public.audit_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,tenant_id,action,record_id) VALUES(auth.uid(),coalesce(new.tenant_id,old.tenant_id),TG_TABLE_NAME||':'||TG_OP,coalesce(new.id,old.id)); RETURN coalesce(new,old); END $$; CREATE TRIGGER property_audit AFTER INSERT OR UPDATE OR DELETE ON public.properties FOR EACH ROW EXECUTE FUNCTION public.audit_change(); CREATE TRIGGER lead_audit AFTER INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.audit_change(); CREATE TRIGGER membership_audit AFTER INSERT OR UPDATE OR DELETE ON public.memberships FOR EACH ROW EXECUTE FUNCTION public.audit_change();
CREATE FUNCTION public.public_properties() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'description',p.description,'location',p.location,'category',p.category,'intent',p.intent,'price',p.price,'area',p.area,'area_unit',p.area_unit,'bedrooms',p.bedrooms,'bathrooms',p.bathrooms,'amenities',p.amenities,'cover_path',p.cover_path,'availability',p.availability,'reference_code',p.reference_code,'verified_at',p.verified_at,'updated_at',p.updated_at) ORDER BY p.updated_at DESC),'[]'::jsonb) FROM public.properties p JOIN public.tenants t ON t.id=p.tenant_id WHERE p.status='published' AND t.status='active' $$; REVOKE ALL ON FUNCTION public.public_properties() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_properties() TO anon,authenticated;
CREATE FUNCTION public.submit_enquiry(listing_id uuid,visitor_name text,visitor_phone text,visitor_email text,enquiry_message text,accepted_consent boolean,preference text DEFAULT 'phone',source_data jsonb DEFAULT '{}') RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.properties; BEGIN IF coalesce(accepted_consent,false)=false THEN RAISE EXCEPTION 'Consent required'; END IF; IF visitor_name IS NULL OR visitor_phone IS NULL OR enquiry_message IS NULL OR visitor_email IS NULL OR length(trim(visitor_name)) NOT BETWEEN 2 AND 100 OR visitor_phone !~ '^[+0-9 ()-]{7,30}$' OR length(enquiry_message)>2000 OR length(visitor_email)>255 OR (visitor_email<>'' AND visitor_email !~ '^[^ @]+@[^ @]+\.[^ @]+$') OR preference NOT IN ('phone','whatsapp','email') OR pg_column_size(source_data)>2048 THEN RAISE EXCEPTION 'Invalid enquiry'; END IF; SELECT x.* INTO p FROM public.properties x JOIN public.tenants t ON t.id=x.tenant_id WHERE x.id=listing_id AND x.status='published' AND t.status='active'; IF p.id IS NULL THEN RAISE EXCEPTION 'Listing unavailable'; END IF; PERFORM pg_advisory_xact_lock(hashtext(visitor_phone)); IF EXISTS(SELECT 1 FROM public.leads WHERE phone=visitor_phone AND created_at>now()-interval '5 minutes') THEN RAISE EXCEPTION 'Please wait before submitting another enquiry'; END IF; INSERT INTO public.leads(tenant_id,branch_id,property_id,assigned_to,name,phone,email,message,consent,contact_preference,source,attribution) VALUES(p.tenant_id,p.branch_id,p.id,p.created_by,trim(visitor_name),visitor_phone,nullif(visitor_email,''),enquiry_message,true,preference,'property enquiry',source_data); RETURN true; END $$; REVOKE ALL ON FUNCTION public.submit_enquiry(uuid,text,text,text,text,boolean,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_enquiry(uuid,text,text,text,text,boolean,text,jsonb) TO anon,authenticated;
CREATE POLICY media_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='property-media' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp') AND EXISTS(SELECT 1 FROM public.properties p WHERE p.id::text=(storage.foldername(name))[2] AND p.created_by=auth.uid()));
CREATE POLICY media_read_owner ON storage.objects FOR SELECT TO authenticated USING(bucket_id='property-media' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY media_read_published ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='property-media' AND EXISTS(SELECT 1 FROM public.properties p JOIN public.tenants t ON t.id=p.tenant_id WHERE p.cover_path=name AND p.status='published' AND t.status='active'));
CREATE POLICY media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='property-media' AND (storage.foldername(name))[1]=auth.uid()::text);